package com.cloudticket.promotion.persistence.mapper;
import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.cloudticket.promotion.persistence.entity.UserCouponEntity; import org.apache.ibatis.annotations.Select; import org.apache.ibatis.annotations.Update; import java.util.List;
public interface UserCouponMapper extends BaseMapper<UserCouponEntity> { @Select("SELECT * FROM promotion_user_coupon WHERE user_id=#{userId} AND status=#{status} ORDER BY term_end_at") List<UserCouponEntity> selectByUserStatus(String userId,String status); @Update("UPDATE promotion_user_coupon SET status=#{to},held_order_id=#{orderId},held_at=CURRENT_TIMESTAMP WHERE id=#{id} AND status='UNUSED'") int hold(String id,String orderId,String to); @Update("UPDATE promotion_user_coupon SET status=#{to},used_at=CASE WHEN #{to}='USED' THEN CURRENT_TIMESTAMP ELSE used_at END WHERE id=#{id} AND status=#{from}") int transition(String id,String from,String to); }
